"use client";

import { useCallback } from "react";

/**
 * Site-wide search over the build-time slim index (public/search-index.json,
 * generated by scripts/build-search-index.mjs).
 *
 * Fuse.js and the index are loaded on the FIRST QUERY, not on mount. Mounting is
 * the wrong moment: the index is 40 KB and fuse.js another ~10 KB gzipped, and
 * a reader who never types was downloading both while the page was still
 * painting. The promise is memoised at module scope so the cost is paid once
 * per page load no matter how many search UIs exist.
 *
 * Fuse options follow full-text best practices for a CJK site:
 * - `ignoreLocation` so matches anywhere in title/description count
 * - a combined `text` field (title + description + tags + Chinese labels)
 *   so Chinese queries (经济/社会…) hit English canonical tags
 * - threshold 0.3 for light typo tolerance without noisy results
 */
const FUSE_OPTIONS = {
  keys: [
    { name: "title", weight: 1 },
    { name: "text", weight: 0.8 },
    { name: "description", weight: 0.6 },
    { name: "tags", weight: 0.5 },
  ],
  ignoreLocation: true,
  minMatchCharLength: 2,
  threshold: 0.3,
  shouldSort: true,
};

let fusePromise = null;

function getFuse() {
  if (!fusePromise) {
    fusePromise = Promise.all([
      import("fuse.js"),
      fetch("/search-index.json").then((res) => res.json()),
    ]).then(([mod, data]) => new mod.default(data, FUSE_OPTIONS));
  }
  return fusePromise;
}

export function usePostSearch() {
  const search = useCallback(async (query) => {
    const trimmed = (query || "").trim();
    if (trimmed.length < 2) return [];
    const fuse = await getFuse();
    return fuse.search(trimmed).map((result) => result.item);
  }, []);

  return { search };
}
